catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }
    g_form.clearMessages(); //clear previous messages


    var uploadedFile = g_form.getValue('upload_file');

    if ((newValue != oldValue) && newValue != '' && newValue != undefined && newValue != null && uploadedFile != '' && uploadedFile != undefined && uploadedFile != null) {

        // Check if the checkbox is checked
        g_form.setValue('re_validate_file', false);
        g_form.clearValue('validation_summary'); //clearing summary due to latest summary information

        var currentTradeMarket = g_form.getDisplayValue('owning_business'); // Get the owning business value
        var uploadType = g_form.getValue('upload_type'); // upload type
        var outcomeSelected = g_form.getValue('outcome');


        var functionName = '';
        if (uploadType == 'bulk_level') {
            functionName = 'validateBulkFileUpload';
        }
        if (uploadType == 'trade_level') {
            functionName = 'validateTradeFileUpload';
        }

        // Function to re-validate the file



        g_form.hideFieldMsg('upload_file', 'Validation has been completed');
        // Show a message indicating validation is in progress
        g_form.setValue('validation_status', 'validation_in_progress'); //Set validation status
        g_form.showFieldMsg('upload_file', 'Please wait until the re-validation is completed...', 'info', true);

        // GlideAjax call to validate the file
        var checkIfEmptyFile = new GlideAjax('x_hsb11_hsbc_mss_o.MSSCustodyBulkFileUpload');
        checkIfEmptyFile.addParam('sysparm_name', functionName);
        checkIfEmptyFile.addParam('sysparm_market', currentTradeMarket);
        checkIfEmptyFile.addParam('sysparm_outcome', outcomeSelected);
        checkIfEmptyFile.getXMLAnswer(checkifemptyRec);

    }


    function checkifemptyRec(response) {

        var dataSummary = '';
        var errorDetails = response.split("/");
        var result = errorDetails[0];
        var summaryTotalCount = errorDetails[1] ? errorDetails[1] : 'NA';
        var summaryErrorRecords = errorDetails[2] ? errorDetails[2] : 'NA';
        var summaryValidRecords = errorDetails[3] ? errorDetails[3] : 'NA';
        var clientValidationSummary = response ? response : 'NA';


        try {

            // MSSCUSTODY 6700 - Handle file type or size validation errors
            if ((result == "Invalid file type") || (result == "File size exceeded") || (result == "Invalid Entries")) {
                // g_form.addErrorMessage(result); // Display error message
                g_form.setValue('validation_status', 'validation_failed'); // Set validation status to failed

                if (response == "Invalid file type") {
                    g_form.addErrorMessage('The file uploaded must be of type .xlsx.');
                    dataSummary += 'Re-validation failed. The file uploaded must be of type .xlsx.';
                } else if (response == "File size exceeded") {
                    g_form.addErrorMessage('The file uploaded exceeds maximum limit of 10MB');
                    dataSummary += 'Re-validation failed. The file uploaded exceeds maximum limit of 10MB';
                } else {
                    g_form.addErrorMessage('Unable to read file. Please check any spaces in the header or in the entries.');
                    dataSummary += 'Re-validation failed. Unable to read file. Please check any spaces in the header or in the entries.';
                }
                // return;
            } else if (result == 'Limit Exceeded') { //more than 500 records
                g_form.addErrorMessage(' The uploaded file contains more than 500 records. Please upload a file with 500 or less than 500 trades');
                dataSummary = 'Re-validation failed. The file contains more than 500 records of allowed limit';
                g_form.setValue('validation_status', 'validation_failed'); //Validation Failed

            } else if (result == "Validation Failed" || result == "Validation Successful") {

                spModal.open({
                    title: 'Validation Errors',
                    widget: 'bulk_file_upload_error_details', // Your widget's sys_id or widget ID
                    widgetInput: {
                        tradeMarket: currentTradeMarket,
                        uploadtype: uploadType,
                        validationSummary: clientValidationSummary
                    },

                    size: 'lg' // large modal

                }).then(function(result) {
                    // Handle modal close if needed
                    //console.log('Modal closed, result:', result);
                });


                //updating status

                if (result == "Validation Successful") {
                    dataSummary += 'Re-validation successful. The data uploaded contains less than 10% of error records';
                    g_form.setValue('validation_status', 'validation_successful'); //Validation Successful
                }

                if (result == "Validation Failed") {

                    //updating status
                    g_form.addErrorMessage('The data uploaded contains more than 10% of error records');
                    dataSummary += 'Re-validation Failed. The data uploaded contains more than 10% of error records';
                    g_form.setValue('validation_status', 'validation_failed'); //Validation Failed
                    //updating status
                }

                //updating status
            } else if (result == "No Errors") {


                dataSummary += 'Re-validation successful. The data uploaded contains no error records';
                g_form.setValue('validation_status', 'validation_successful'); //Validation Successful


            } else if (result == "No records Found") {
                g_form.addErrorMessage('The file uploaded seems to be empty. Please review');
                dataSummary += 'Re-Validation failed. The file uploaded seems to be empty. Please review';

                //  g_form.setValue('validation_progress', 'step5'); //Validation Failed

                spModal.open({
                    title: 'Empty File Alert!',
                    widget: 'bulk_file_upload_empty_alert', // Your widget's sys_id or widget ID
                    widgetInput: {
                        //tradeMarket: currentTradeMarket
                        //attachmentSysId: attachmentSysId,
                    },

                    size: 'lg' // large modal

                }).then(function(result) {
                    // Handle modal close if needed
                    // console.log('Modal closed, result:', result);
                });

                g_form.setValue('validation_status', 'validation_failed'); //Validation Failed


            } else {
                //error handling for a  corrupted file
                g_form.addErrorMessage('The file uploaded seems to be corrupted. Please review');
                dataSummary += 'Re-Validation failed. The file uploaded seems to be corrupted. Please review';
                g_form.setValue('validation_status', 'validation_failed'); //Validation Failed //exception handling if any other response received

            }

        } catch (ex) {
            g_form.addErrorMessage('Error from CLient ' + ex);
        }



        //validation Summary
        var htmlContent = '<p style="color: black;">Total Records : <strong>' + summaryTotalCount + '</strong></p>' +
            '<p style="color: black;">Error Records : <strong style="color: red;">' + summaryErrorRecords + '</strong></p>' + // Label black, value red
            '<p style="color: black;">Valid Records : <strong style="color: green;">' + summaryValidRecords + '</strong></p>' + // Label black, value green
            '<p style="color: black;">Summary: &nbsp <br>' + dataSummary + '</p>'; // Note label not bold, overall black
        g_form.setValue('validation_summary', htmlContent);
        //validation Summary

        g_form.hideFieldMsg('upload_file', 'Please wait until the re-validation is completed...');
        g_form.showFieldMsg('upload_file', 'Re-validation has been completed', 'info', true);

        //Type appropriate comment here, and begin script below

    }
}
